        self.assertEqual(compact_wrist_group["embellishmentOptions"][0]["simcOptions"]["embellishment"], "blue_silken_lining")
        self.assertEqual(compact_wrist_group["embellishmentOptions"][0]["label"], "蓝色丝质内衬")
