    def test_http_websim_simulate_blocks_candidate_gear_without_running_or_saving(self):
        conn = sqlite3.connect(self.db_path)
        try:
            self.seed_websim_encoder_nodes(conn)
        finally:
            conn.close()
        simc_bin = Path(self.tmp.name) / "fake-candidate-gear-websim-simc"
        captured_profile = Path(self.tmp.name) / "candidate-gear-websim-profile.txt"
        simc_bin.write_text(
            "#!/bin/sh\n"
            f"cat > {captured_profile}\n"
            "printf 'DPS Ranking:\\n1. Should_Not_Run 999999 dps\\n'\n",
            encoding="utf-8",
        )
        simc_bin.chmod(0o755)
        os.environ["WOW_SIMC_BIN"] = str(simc_bin)
        server = ThreadingHTTPServer(("127.0.0.1", 0), self.backend.Handler)
        thread = threading.Thread(target=server.serve_forever, daemon=True)
        thread.start()
        try:
            base = f"http://127.0.0.1:{server.server_port}"
            request = Request(
                f"{base}/api/websim/simulate",
                data=json.dumps(self.websim_encoder_payload({
                    "gearSelection": {
                        "items": [
                            {
                                "slot": "head",
                                "itemId": 250060,
                                "name": "Voidbreaker's Veil",
                                "sourceType": "verifiedLoot",
                            }
                        ]
                    }
                })).encode("utf-8"),
                headers={"Content-Type": "application/json"},
                method="POST",
            )
            with urlopen(request) as response:
                result = json.loads(response.read().decode("utf-8"))
        finally:
            server.shutdown()
            server.server_close()
            thread.join(timeout=2)

        conn = sqlite3.connect(self.db_path)
        try:
            task_count = conn.execute("SELECT COUNT(*) FROM simulator_tasks").fetchone()[0]
        finally:
            conn.close()
        self.assertEqual(result["status"], "blocked")
        self.assertEqual(result["agent"]["status"], "needs_clarification")
        self.assertEqual(result["agent"]["missingSlots"], ["gear"])
        self.assertEqual(result["talentEncoding"]["status"], "encoded")
        self.assertFalse(result["simulation"]["ran"])
        self.assertFalse(captured_profile.exists())
        self.assertEqual(task_count, 0)

    def test_http_talents_api_routes_reuse_authority_rules(self):
        conn = sqlite3.connect(self.db_path)
        try:
            self.seed_websim_encoder_nodes(conn)
        finally:
            conn.close()

        server = ThreadingHTTPServer(("127.0.0.1", 0), self.backend.Handler)
        thread = threading.Thread(target=server.serve_forever, daemon=True)
        thread.start()
        base = f"http://127.0.0.1:{server.server_port}"
        try:
            with urlopen(f"{base}/api/talents/tree?class=mage&spec=arcane&hero=spellslinger") as response:
                tree = json.loads(response.read().decode("utf-8"))
            self.assertEqual(tree["talentSchemaRevision"], self.websim_payload.TALENT_SCHEMA_REVISION)
            self.assertEqual(tree["talentAuthority"]["runtimeSource"], "simc")
            self.assertEqual(tree["nodeAvailability"]["source"], "backend_validation")
            self.assertEqual(set(tree["nodeAvailability"]["nodes"]), {node["id"] for node in tree["nodes"]})

            validate_request = Request(
                f"{base}/api/talents/validate",
                data=json.dumps({
                    "classKey": "mage",
                    "specKey": "arcane",
                    "heroKey": "spellslinger",
                    "talentState": {
                        "selectedNodes": [
                            {"id": "simc-class-1001-mage-arcane", "rank": 1},
                            {"id": "simc-spec-2001-mage-arcane", "rank": 1},
                            {"id": "simc-hero-3001-mage-arcane-spellslinger", "rank": 1},
                        ]
                    },
                }).encode("utf-8"),
                headers={"Content-Type": "application/json"},
                method="POST",
            )
            with urlopen(validate_request) as response:
                validation = json.loads(response.read().decode("utf-8"))
            self.assertEqual(validation["status"], "encoded")
            self.assertEqual(validation["selectedCounts"], {"class": 1, "spec": 1, "hero": 1})
            self.assertEqual(validation["nodeAvailability"]["source"], "backend_validation")
            self.assertEqual(
                set(validation["nodeAvailability"]["nodes"]),
                {node["id"] for node in tree["nodes"]},
            )

            export_request = Request(
                f"{base}/api/talents/export",
                data=json.dumps({
                    "classKey": "mage",
                    "specKey": "arcane",
                    "heroKey": "spellslinger",
                    "talentState": validation["talentState"],
                }).encode("utf-8"),
                headers={"Content-Type": "application/json"},
                method="POST",
            )
            with urlopen(export_request) as response:
                exported = json.loads(response.read().decode("utf-8"))
            self.assertTrue(exported["websimExportCode"].startswith("websim:mage:arcane:spellslinger:"))

            import_request = Request(
                f"{base}/api/talents/import",
                data=json.dumps({"code": exported["websimExportCode"]}).encode("utf-8"),
                headers={"Content-Type": "application/json"},
                method="POST",
            )
            with urlopen(import_request) as response:
                imported = json.loads(response.read().decode("utf-8"))
            self.assertEqual(imported["classKey"], "mage")
            self.assertEqual(imported["specKey"], "arcane")
            self.assertEqual(imported["heroKey"], "spellslinger")
            imported_nodes = sorted(imported["talentState"]["selectedNodes"], key=lambda item: item["id"])
            validated_nodes = sorted(validation["talentState"]["selectedNodes"], key=lambda item: item["id"])
            self.assertEqual(imported_nodes, validated_nodes)
        finally:
            server.shutdown()
            server.server_close()
            thread.join(timeout=2)

    def test_http_postgres_only_legacy_profile_uses_pg_talent_authority(self):
        conn = sqlite3.connect(self.db_path)
        try:
            self.seed_websim_encoder_nodes(conn)
            talent_payload = self.websim_payload.get_websim_talents(
                conn,
                "mage",
                "arcane",
                "spellslinger",
            )
        finally:
            conn.close()

        class FakePostgresStore:
            def __init__(self, payload):
                self.payload = payload
                self.calls = []

            def get_websim_talents(self, class_key, spec_key, hero_key=""):
                self.calls.append((class_key, spec_key, hero_key))
                return self.payload

        store = FakePostgresStore(talent_payload)
        original_postgres_only = self.backend.postgres_only_runtime_enabled
        original_cache_store = self.backend.cache_data_store
        self.backend.postgres_only_runtime_enabled = lambda: True
        self.backend.cache_data_store = lambda: store
        server = ThreadingHTTPServer(("127.0.0.1", 0), self.backend.Handler)
        thread = threading.Thread(target=server.serve_forever, daemon=True)
        thread.start()
        try:
            request = Request(
                f"http://127.0.0.1:{server.server_port}/api/websim/profile",
                data=json.dumps(self.websim_encoder_payload({"gearSelection": {"items": []}})).encode("utf-8"),
                headers={"Content-Type": "application/json"},
                method="POST",
            )
            with urlopen(request) as response:
                result = json.loads(response.read().decode("utf-8"))
        finally:
            server.shutdown()
            server.server_close()
            thread.join(timeout=2)
            self.backend.postgres_only_runtime_enabled = original_postgres_only
            self.backend.cache_data_store = original_cache_store

        self.assertEqual(result["talentEncoding"]["status"], "encoded")
        self.assertIn("class_talents=", result["profile"])
        self.assertIn("spec_talents=", result["profile"])
        self.assertIn("hero_talents=", result["profile"])
        self.assertEqual(len(store.calls), 1)

    def test_http_postgres_only_legacy_profile_fails_closed_without_pg_talent_authority(self):
        class BrokenPostgresStore:
            def get_websim_talents(self, class_key, spec_key, hero_key=""):
                raise RuntimeError("pg down")

        store_state = {"value": None}
        original_postgres_only = self.backend.postgres_only_runtime_enabled
        original_cache_store = self.backend.cache_data_store
        original_init_db = self.backend.init_db
        self.backend.postgres_only_runtime_enabled = lambda: True
        self.backend.cache_data_store = lambda: store_state["value"]
        self.backend.init_db = lambda: (_ for _ in ()).throw(
            AssertionError("SQLite fallback should not be used for PG profile reads")
        )
        server = ThreadingHTTPServer(("127.0.0.1", 0), self.backend.Handler)
        thread = threading.Thread(target=server.serve_forever, daemon=True)
        thread.start()
        try:
            for store in (None, BrokenPostgresStore()):
                store_state["value"] = store
                request = Request(
                    f"http://127.0.0.1:{server.server_port}/api/websim/profile",
                    data=json.dumps(self.websim_encoder_payload({"gearSelection": {"items": []}})).encode("utf-8"),
                    headers={"Content-Type": "application/json"},
                    method="POST",
                )
                with self.subTest(store=type(store).__name__), urlopen(request) as response:
                    result = json.loads(response.read().decode("utf-8"))
                self.assertEqual(result["talentEncoding"]["status"], "failed")
                self.assertEqual(result["profileReadiness"]["talentReady"], False)
                self.assertNotIn("talents=", result["profile"])
        finally:
            server.shutdown()
            server.server_close()
            thread.join(timeout=2)
            self.backend.postgres_only_runtime_enabled = original_postgres_only
            self.backend.cache_data_store = original_cache_store
            self.backend.init_db = original_init_db

